import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Vector2,
} from 'three/webgpu';
import { texture } from 'three/tsl';

/**
 * @param {Object} config - NodeConfig from the system
 * @param {Object} ctx - NodeContext with textureLoader, etc.
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Load the texture from the configured asset URL
  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');

  // Set texture wrapping to clamp (default is repeat, but we use exact region)
  tex.wrapS = tex.wrapT = 1000; // ClampToEdgeWrapping

  // Atlas region: source rect (0,0,512,320). If the full texture is exactly 512x320,
  // we don't need UV offset. But we set it explicitly for clarity.
  tex.repeat.set(1, 1);
  tex.offset.set(0, 0);

  // Aspect ratio of the texture region
  const aspect = 512 / 320; // ~1.6

  // Geometry: width = 1 unit, height = 1 / aspect to preserve ratio
  const geometry = new PlaneGeometry(1, 1 / aspect);

  // Material using TSL texture node
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(tex),
    transparent: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);

  // Apply position, rotation, scale from config
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Attach cleanup function to dispose resources
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  // No handlers needed since there are no interactions
  mesh.userData.handlers = {};

  return mesh;
}
